const now = ctx.now();
const rows = await ctx.db.list("{{param.entity}}", { filter: [{ field: "{{param.status_field}}", op: "neq", value: "{{param.done_value}}" }], limit: 1000 });
const late: string[] = [];
for (const r of rows) {
  if (String(r["{{param.status_field}}"] ?? "") === "{{param.done_value}}") continue;
  const raw = String(r["{{param.due_field}}"] ?? "");
  if (!raw) continue;
  const due = new Date(raw).getTime() + (raw.length <= 10 ? 24 * 3600 * 1000 : 0);
  if (!Number.isFinite(due) || due > now.getTime()) continue;
  const label = String(r["{{param.entity.label_field}}"] ?? r["id"]);
  late.push(`${label} (due ${raw.slice(0, 10)})`);
  if (r["overdue_since"]) continue;
  await ctx.db.update("{{param.entity}}", String(r["id"]), { overdue_since: now.toISOString() });
  const refField = "{{param.assignee_ref}}";
  const who = refField ? String(r[refField] ?? "") : "";
  if (who) {
    const person = await ctx.db.get("{{param.assignee_ref.ref}}", who);
    if (person && person["user_id"]) await ctx.notify({ title: `Overdue: ${label}`, body: `It was due ${raw.slice(0, 10)}. Finish it or move the date.`, user: String(person["user_id"]) });
  }
}
if (late.length > 0) await ctx.notify({ title: `${late.length} overdue {{param.entity|title}} ${late.length === 1 ? "row" : "rows"}`, body: late.slice(0, 15).join("\n"), role: "{{param.notify_role}}" });
ctx.log(`overdue: ${late.length}`);
